def transform(grid):
    g = np.asarray(grid)
    top, bot = g[0], g[-1]
    # Bands are stacked vertically if the top and bottom rows are each one colour and differ.
    vertical_stack = (len(set(top.tolist())) == 1 and len(set(bot.tolist())) == 1
                      and top[0] != bot[0])
    cols = sorted(set(g.flatten().tolist()))
    keys = {}
    for c in cols:
        ys, xs = np.nonzero(g == c)
        keys[c] = ys.mean() if vertical_stack else xs.mean()
    order = sorted(cols, key=lambda c: keys[c])
    n = len(order)
    if vertical_stack:
        out = np.zeros((n, 1), dtype=int)
    else:
        out = np.zeros((1, n), dtype=int)
    emit(out, f"Allocate a {'column' if vertical_stack else 'row'} strip with one cell per band ({n} bands).")
    for i, c in enumerate(order):
        if vertical_stack:
            out[i, 0] = c
        else:
            out[0, i] = c
        emit(out, f"Band {i+1} in order is colour {c}; write it into cell {i}.")
    return out
